{"code": "import pandas as pd, numpy as np, statsmodels.formula.api as smf
df=pd.read_csv('data/explore.csv');print(df.shape);print(df.head());print(df.isna().sum().sum())
ex=['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']
for e in ex:
    m=smf.ols(f'yield_kg~{e}+C(farm)',df).fit()
    print(e, round(m.params[e],4), round(m.pvalues[e],4), round(np.corrcoef(df[e],df.yield_kg)[0,1],3))"}
